 @SuppressWarnings("unchecked") private static Map<UUID,ServerPlayer> online(ServerPlayer p){try{var f=net.minecraft.server.players.PlayerList.class.getDeclaredField("playersByUUID");f.setAccessible(true);return (Map<UUID,ServerPlayer>)f.get(p.server.getPlayerList());}catch(Exception e){throw new RuntimeException(e);}}
 private static ServerPlayer player(GameTestHelper t){var w=t.getLevel();var p=new ServerPlayer(w.getServer(),w,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"RewardTest"),ClientInformation.createDefault());p.connection=new Listener(p);p.setGameMode(GameType.SURVIVAL);try{var f=ServerPlayer.class.getDeclaredField("spawnInvulnerableTime");f.setAccessible(true);f.setInt(p,0);}catch(Exception e){throw new RuntimeException(e);}p.setNoGravity(true);p.moveTo(t.absoluteVec(new Vec3(8,2,8)));p.setOnGround(true);w.addNewPlayer(p);online(p).put(p.getUUID(),p);return p;}
 static int checks;
 static void check(GameTestHelper t,boolean b,String label){checks++;t.assertTrue(b,label);System.out.println("REWARDS_CHECK "+label);}
 static int count(ServerPlayer p,String id){return Runes.inventoryCount(p,RewardContent.item(id));}
 static void clear(ServerPlayer p){for(int i=0;i<36;i++)p.getInventory().setItem(i,ItemStack.EMPTY);}
 static void accessory(ServerPlayer p,String slot,String id){var handler=top.theillusivec4.curios.api.CuriosApi.getCuriosInventory(p).orElseThrow();var stacks=handler.getStacksHandler(slot).orElseThrow().getStacks();stacks.setStackInSlot(0,id.isEmpty()?ItemStack.EMPTY:new ItemStack(RewardContent.item(id)));p.tick();}
 static Zombie zombie(GameTestHelper t,ServerPlayer p){var z=EntityType.ZOMBIE.create(t.getLevel());z.moveTo(p.position().add(0,0,2));z.setNoAi(true);z.setNoGravity(true);z.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(100);z.setHealth(100);z.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.ARMOR).setBaseValue(0);t.getLevel().addFreshEntity(z);return z;}
